// Helper: search trains by query
export function searchExpandedTrains(query: string, limit = 15): QuickTrain[] {
  const q = query.toLowerCase().trim();
  if (!q) return EXPANDED_TRAINS.slice(0, limit);
  return EXPANDED_TRAINS
    .filter(t =>
      t.number.includes(q) ||
      t.name.toLowerCase().includes(q) ||
      t.fromCode.toLowerCase().includes(q) ||
      t.toCode.toLowerCase().includes(q) ||
      t.from.toLowerCase().includes(q) ||
      t.to.toLowerCase().includes(q) ||
      t.type.toLowerCase().includes(q) ||
      (q === 'vande bharat' && t.type === 'Vande Bharat') ||
      (q === 'shatabdi' && t.type === 'Shatabdi') ||
      (q === 'rajdhani' && t.type === 'Rajdhani')
    )
    .slice(0, limit);
}

// Group by category
export const VANDE_BHARAT_TRAINS = EXPANDED_TRAINS.filter(t => t.type === 'Vande Bharat');
export const SHATABDI_TRAINS = EXPANDED_TRAINS.filter(t => t.type === 'Shatabdi');
export const RAJDHANI_TRAINS = EXPANDED_TRAINS.filter(t => t.type === 'Rajdhani');
